import numpy as npimport pandas as pdimport matplotlib.pyplot as pltfrom sklearn.model_selection import train_test_split # should robably validate moduls using test data igfrom sklearn.linear_model import LogisticRegressionfrom tqdm import tqdmfrom sklearn.model_selection import train_test_splitfrom sklearn.model_selection import GridSearchCVfrom sklearn.linear_model import LogisticRegressionfrom sklearn.preprocessing import StandardScalerimport math##### leave one out### male ###male_individual_level_data_0_1 = pd.DataFrame()for clusterx in (range(0,26)):        # read in     base_path = "/Users/ggraham/Desktop/multiome_poa/Sex Classifier and Linearity/progress_classifier/Including DARs/degs_0.1_f_m_dars_0.05_f_m/"    path = f"{base_path}cluster_{clusterx}.csv"    cluster_data = pd.read_csv(path)        males = cluster_data['individual'][cluster_data['Status'].isin(['M'])]        for male in set(males):        # set up training data        training_data = cluster_data[cluster_data['Status'].isin(['M','F'])]        training_data_2 = training_data[training_data['individual'] != male] ## exclude male                training_labels = np.where(training_data_2['Status']=='M', 0, 1)        training_matrix = training_data_2.iloc[:,3:].to_numpy()                test_data = training_data[training_data['individual'] == male] #only male        test_matrix = test_data.iloc[:,3:].to_numpy()                # scale data        scaler = StandardScaler()        scaler.fit(training_matrix)        train_std_x = scaler.transform(training_matrix)        test_std_x = scaler.transform(test_matrix)        #initialize model        log = LogisticRegression(C=10)        log.fit(train_std_x, training_labels)            prediction = log.predict(test_std_x)[0]        proba = log.predict_proba(test_std_x)[:,1]                ind_data = pd.DataFrame({'individual':[male],                                 'status':'m',                                 'prediction':[prediction],                                 'proba':proba,                                 'cluster':[clusterx]})        male_individual_level_data_0_1 = pd.concat([male_individual_level_data_0_1, ind_data])male_individual_level_data_0_1# ok so this is definitely wron if it thinks males are females in cluster 0male_individual_level_data_0_1.groupby('cluster')['prediction'].mean()                           ### female ###individual_level_data_0_1_f = pd.DataFrame()for clusterx in (range(0,26)):    # read in     base_path = "/Users/ggraham/Desktop/multiome_poa/Sex Classifier and Linearity/progress_classifier/Including DARs/degs_0.1_f_m_dars_0.05_f_m/"    path = f"{base_path}cluster_{clusterx}.csv"    cluster_data = pd.read_csv(path)        female = cluster_data['individual'][cluster_data['Status'].isin(['F'])]        for female in set(female):        # set up training data        training_data = cluster_data[cluster_data['Status'].isin(['M','F'])]        training_data_2 = training_data[training_data['individual'] != female] ## exclude male                training_labels = np.where(training_data_2['Status']=='M', 0, 1)        training_matrix = training_data_2.iloc[:,3:].to_numpy()                test_data = training_data[training_data['individual'] == female] #only male        test_matrix = test_data.iloc[:,3:].to_numpy()                # scale data        scaler = StandardScaler()        scaler.fit(training_matrix)        train_std_x = scaler.transform(training_matrix)        test_std_x = scaler.transform(test_matrix)        #initialize model        log = LogisticRegression(C=10)        log.fit(train_std_x, training_labels)            prediction = log.predict(test_std_x)[0]        proba = log.predict_proba(test_std_x)[:,1]                ind_data = pd.DataFrame({'individual':[female],                                 'status':'f',                                 'prediction':[prediction],                                 'proba':proba,                                 'cluster':[clusterx]})        individual_level_data_0_1_f = pd.concat([individual_level_data_0_1_f, ind_data])        individual_level_data_0_1_f['prediction'].mean()individual_level_data_0_1_findividual_level_data_0_1_f.groupby('cluster')['prediction'].mean()        full_data = pd.concat([individual_level_data_0_1_f,male_individual_level_data_0_1 ], ignore_index= True)full_data.to_csv("/Users/ggraham/Desktop/multiome_poa/Sex Classifier and Linearity/progress_classifier/Including DARs/logistic_mf_validation_07_13_2026.csv")